const DAY_MS = 86_400_000;

/** Calendar arithmetic in UTC, clamping the day before restoring the time. */
export function billingPeriodEnd(start: Date, interval: BillingInterval) {
  const end = new Date(start);
  const day = end.getUTCDate();
  end.setUTCDate(1);
  end.setUTCMonth(end.getUTCMonth() + (interval === \"annual\" ? 12 : 1));
  const lastDay = new Date(Date.UTC(end.getUTCFullYear(), end.getUTCMonth() + 1, 0)).getUTCDate();
  end.setUTCDate(Math.min(day, lastDay));
  return toIsoTimestamp(end);
